// ì¡°í•©ì‹ íƒœê·¸ íŒë³„ (ê³µë°± í¬í•¨ ì—¬ë¶€ë¡œ íŒë‹¨ - ê¸°ì¡´ + í¬í•¨ íƒœê·¸ë„ í˜¸í™˜)
function isComboTag(tag) {
  if (!tag) return false;
  // ê¸°ì¡´ "+" ë˜ëŠ” ìƒˆë¡œìš´ ê³µë°± í˜•ì‹ ëª¨ë‘ ì§€ì›
  return tag.includes("+") || (tag.includes(" ") && COMBO_TAG_TRAITS.some(t => tag.startsWith(t)));
}

