/* =========================================================
   ìœ í‹¸ë¦¬í‹° í•¨ìˆ˜
   ========================================================= */
function parsePlatforms(p) {
  try { const arr = JSON.parse(p || "[]"); return Array.isArray(arr) ? arr : []; }
  catch { return []; }
}

// ðŸ†• í”Œëž«í¼ ìš”ì•½ í‘œì‹œ (ì²« ë²ˆì§¸ë§Œ + ë‚˜ë¨¸ì§€ ê°œìˆ˜)
function formatPlatformShort(platforms) {
  const plats = typeof platforms === "string" ? parsePlatforms(platforms) : (platforms || []);
  if (!plats.length) return "-";
  if (plats.length === 1) return plats[0];
  return `${plats[0]} +${plats.length - 1}`;
}

function getWinRate(wins, losses) {
  const total = (wins || 0) + (losses || 0);
  return total > 0 ? ((wins || 0) / total * 100).toFixed(1) : "-";
}

// ðŸ†• ë“±ë¡ í›„ í•œë‹¬ ì´ë‚´ì¸ì§€ í™•ì¸
function isNewNovel(createdAt) {
  if (!createdAt) return false;
  const oneMonthAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
  return createdAt > oneMonthAgo;
}

// ðŸ·ï¸ ìž¥ë¥´ íŒŒì‹± í—¬í¼ (JSON ë°°ì—´ ë˜ëŠ” ë‹¨ì¼ ë¬¸ìžì—´ â†’ ë°°ì—´)
function parseGenreArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed;
    return [parsed];
  } catch {
    return value ? [value] : [];
  }
}

// ðŸ·ï¸ ìž¥ë¥´ ì²« ë²ˆì§¸ ê°’ ê°€ì ¸ì˜¤ê¸° (ì¹´ë“œ í‘œì‹œìš©)
function getFirstGenre(value) {
  const arr = parseGenreArray(value);
  return arr.length > 0 ? arr[0] : "";
}

/* =========================================================
   ðŸ–¼ï¸ í‘œì§€ ë¼ì´ë¸ŒëŸ¬ë¦¬ ì‹œìŠ¤í…œ (v3.4.7 - ë ˆê±°ì‹œ FileSystem API)
   ========================================================= */

// í‘œì§€ ì €ìž¥ ë””ë ‰í† ë¦¬ (ë ˆê±°ì‹œ API)
const COVER_DIR = FileSystem.documentDirectory + "covers/";

// ì••ì¶• ì„¤ì • ë§µ
const COMPRESSION_PRESETS = {
  original: { quality: 1.0, maxSize: null },        // ì›ë³¸ ìœ ì§€
  light: { quality: 0.8, maxSize: 1200 },           // ê°€ë²¼ìš´ ì••ì¶• (ê¸°ë³¸ê°’)
  medium: { quality: 0.6, maxSize: 800 },           // ì¤‘ê°„ ì••ì¶•
  heavy: { quality: 0.4, maxSize: 600 },            // ê°•í•œ ì••ì¶•
};

// í‘œì§€ ë””ë ‰í† ë¦¬ ì´ˆê¸°í™” (ë ˆê±°ì‹œ API)
async function ensureCoverDir() {
  try {
    const dirInfo = await FileSystem.getInfoAsync(COVER_DIR);
    if (!dirInfo.exists) {
      await FileSystem.makeDirectoryAsync(COVER_DIR, { intermediates: true });
    }
  } catch (e) {
    console.warn("ensureCoverDir error:", e);
  }
}

// ì´ë¯¸ì§€ë¥¼ í‘œì§€ ë¼ì´ë¸ŒëŸ¬ë¦¬ì— ì €ìž¥ (ë ˆê±°ì‹œ API)
// ðŸ”§ v3.5.1: content:// URI ì§€ì› ê°•í™” - ì—¬ëŸ¬ ë°©ë²• ì‹œë„
async function saveCoverToLibrary(sourceUri, compressionLevel = "light") {
  try {
    await ensureCoverDir();
    
    const id = uuid();
    const fileName = `${id}.jpg`;
    const destUri = COVER_DIR + fileName;
    
    // ðŸ”§ v3.5.1: ì—¬ëŸ¬ ë°©ë²•ìœ¼ë¡œ ì‹œë„
    // ë°©ë²• 1: copyAsync (file:// URIì—ì„œ ìž˜ ìž‘ë™)
    // ë°©ë²• 2: downloadAsync (ì¼ë¶€ content:// URIì—ì„œ ìž‘ë™)
    
    let success = false;
    
    // ë°©ë²• 1: copyAsync ì‹œë„
    try {
      await FileSystem.copyAsync({
        from: sourceUri,
        to: destUri,
      });
      success = true;
    } catch (copyError) {
      console.warn("saveCoverToLibrary: copyAsync ì‹¤íŒ¨, downloadAsync ì‹œë„:", copyError.message);
    }
    
    // ë°©ë²• 2: downloadAsync ì‹œë„ (copyAsync ì‹¤íŒ¨ ì‹œ)
    if (!success) {
      try {
        const downloadResult = await FileSystem.downloadAsync(sourceUri, destUri);
        if (downloadResult.status === 200) {
          success = true;
        }
      } catch (downloadError) {
        console.warn("saveCoverToLibrary: downloadAsyncë„ ì‹¤íŒ¨:", downloadError.message);
      }
    }
    
    if (!success) {
      return null;
    }
    
    // ë³µì‚¬ í›„ ëŒ€ìƒ íŒŒì¼ ì •ë³´ í™•ì¸
    const destInfo = await FileSystem.getInfoAsync(destUri);
    if (!destInfo.exists) {
      console.warn("saveCoverToLibrary: ë³µì‚¬ í›„ ëŒ€ìƒ íŒŒì¼ì´ ì¡´ìž¬í•˜ì§€ ì•ŠìŒ");
      return null;
    }
    
    return {
      id,
      file_path: destUri,
      file_size: destInfo.size || 0,
    };
  } catch (e) {
    console.warn("saveCoverToLibrary error:", e.message);
    return null;
  }
}

// í‘œì§€ ë¼ì´ë¸ŒëŸ¬ë¦¬ì—ì„œ ì´ë¯¸ì§€ ì‚­ì œ (ë ˆê±°ì‹œ API)
async function deleteCoverFromLibrary(filePath) {
  try {
    const fileInfo = await FileSystem.getInfoAsync(filePath);
    if (fileInfo.exists) {
      await FileSystem.deleteAsync(filePath, { idempotent: true });
    }
  } catch (e) {
    console.warn("deleteCoverFromLibrary error:", e);
  }
}

// í‘œì§€ ë¼ì´ë¸ŒëŸ¬ë¦¬ ì „ì²´ ìš©ëŸ‰ ê³„ì‚° (ë ˆê±°ì‹œ API)
async function getCoverLibrarySize() {
  try {
    await ensureCoverDir();
    const dirInfo = await FileSystem.getInfoAsync(COVER_DIR);
    if (!dirInfo.exists) return 0;
    
    const files = await FileSystem.readDirectoryAsync(COVER_DIR);
    let totalSize = 0;
    
    for (const fileName of files) {
      try {
        const fileInfo = await FileSystem.getInfoAsync(COVER_DIR + fileName);
        if (fileInfo.exists && fileInfo.size) {
          totalSize += fileInfo.size;
        }
      } catch (e) {
        // ê°œë³„ íŒŒì¼ ì˜¤ë¥˜ëŠ” ë¬´ì‹œ
      }
    }
    return totalSize;
  } catch (e) {
    console.warn("getCoverLibrarySize error:", e);
    return 0;
  }
}

// ìš©ëŸ‰ í¬ë§·íŒ… í—¬í¼
function formatFileSize(bytes) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
  if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  return (bytes / (1024 * 1024 * 1024)).toFixed(2) + " GB";
}

