// ðŸ“· í‘œì§€ ì´ë¯¸ì§€ ì»´í¬ë„ŒíŠ¸ (expo-image ì‚¬ìš©, ë©”ëª¨ì´ì œì´ì…˜)
const CoverImage = memo(({ uri, platforms, platformCovers = {}, size = 50, theme }) => {
  // ìµœì¢… URI ê³„ì‚° (ë™ê¸°ì ìœ¼ë¡œ ì¦‰ì‹œ)
  const finalUri = useMemo(() => {
    if (uri) return uri;
    if (platforms) {
      const plats = typeof platforms === "string" ? parsePlatforms(platforms) : platforms;
      for (const p of plats) {
        if (platformCovers[p]) return platformCovers[p];
      }
    }
    return null;
  }, [uri, platforms, platformCovers]);
  
  // ì´ë¯¸ì§€ ì—†ìœ¼ë©´ í”Œë ˆì´ìŠ¤í™€ë”
  if (!finalUri) {
    return (
      <View style={{ 
        width: size, 
        height: size * 1.4, 
        borderRadius: 6, 
        marginRight: 10,
        backgroundColor: theme?.line || '#e5e7eb',
        justifyContent: 'center',
        alignItems: 'center'
      }}>
        <Text style={{ fontSize: size * 0.3, color: theme?.sub || '#9ca3af' }}>ðŸ“–</Text>
      </View>
    );
  }
  
  return (
    <ExpoImage
      source={{ uri: finalUri }}
      style={{ width: size, height: size * 1.4, borderRadius: 6, marginRight: 10 }}
      contentFit="cover"
      cachePolicy="memory-disk"
      transition={150}
      placeholder={{ blurhash: 'L6PZfSi_.AyE_3t7t7R**0o#DgR4' }}
    />
  );
});

// ðŸ“± NovelCard: í™ˆ í™”ë©´ ìž‘í’ˆ ì¹´ë“œ ì»´í¬ë„ŒíŠ¸ (ë©”ëª¨ì´ì œì´ì…˜ìœ¼ë¡œ ì„±ëŠ¥ ìµœì í™”)
const NovelCard = memo(({ 
  item, 
  index, 
  onPress, 
  onLongPress, // ðŸ†• v3.4.1: ê¸¸ê²Œ ëˆ„ë¥´ë©´ ì „ì²´ ì œëª© í‘œì‹œ
  onTogglePin, 
  onLinkPress,
  compareMode, 
  isComparing, 
  platformCovers, 
  theme, 
  isDark 
}) => {
  // ë©”ëª¨ì´ì œì´ì…˜ëœ ê³„ì‚°ë“¤
  const winRate = useMemo(() => getWinRate(item.wins, item.losses), [item.wins, item.losses]);
  const isNew = useMemo(() => isNewNovel(item.created_at), [item.created_at]);
  const plats = useMemo(() => parsePlatforms(item.platforms), [item.platforms]);
  
  const episodeText = useMemo(() => {
    const hasGaiden = item.gaiden_status && item.gaiden_status !== "none";
    if (hasGaiden) {
      const gaidenPart = item.gaiden_total_episodes > 0 
        ? `ì™¸ì „ ${item.gaiden_read_count || 0}/${item.gaiden_total_episodes}í™”`
        : `ì™¸ì „ ${item.gaiden_read_count || 0}í™”`;
      const mainPart = item.total_episodes > 0 ? `ë³¸íŽ¸ ${item.total_episodes}í™”` : "";
      return mainPart ? `${gaidenPart} (${mainPart})` : gaidenPart;
    }
    return item.total_episodes > 0 
      ? `${item.read_count}/${item.total_episodes}í™”` 
      : `${item.read_count}í™”`;
  }, [item.gaiden_status, item.gaiden_read_count, item.gaiden_total_episodes, item.total_episodes, item.read_count]);

  const hasAwards = useMemo(() => item.awards && parseAwards(item.awards).length > 0, [item.awards]);

  return (
    <TouchableOpacity
      onPress={onPress}
      onLongPress={onLongPress}
      delayLongPress={500}
      activeOpacity={0.7}
      style={{
        padding: 14,
        backgroundColor: isComparing ? (isDark ? "#1e3a5f" : "#e0f2fe") : theme.card,
        borderRadius: 14,
        borderWidth: isComparing ? 2 : (isNew ? 2 : 1),
        borderColor: isComparing ? theme.primary : (isNew ? "#fbbf24" : theme.line),
        marginBottom: 10,
      }}
    >
      <View style={{ flexDirection: "row" }}>
        {/* í‘œì§€ ì´ë¯¸ì§€ */}
        <CoverImage uri={item.cover_image} platforms={item.platforms} platformCovers={platformCovers} size={65} theme={theme} />
        
        <View style={{ flex: 1 }}>
          {/* 1ì¤„: ìˆœìœ„ + ì¦ê²¨ì°¾ê¸° + NEW + ì œëª© + í‹°ì–´ */}
          <View style={{ flexDirection: "row", alignItems: "center", marginBottom: 6 }}>
            <TouchableOpacity 
              onPress={onTogglePin}
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
            >
              <Text style={{ fontSize: 16, color: item.pinned ? "#fbbf24" : theme.sub, marginRight: 4 }}>
                {item.pinned ? "â˜…" : "â˜†"}
              </Text>
            </TouchableOpacity>
            {isNew && (
              <View style={{ backgroundColor: "#fbbf24", paddingHorizontal: 5, paddingVertical: 2, borderRadius: 4, marginRight: 5 }}>
                <Text style={{ color: "#000", fontSize: 9, fontWeight: "800" }}>NEW</Text>
              </View>
            )}
            <Text style={{ fontWeight: "800", fontSize: 15, color: theme.text, flex: 1 }} numberOfLines={1}>
              {index + 1}. {item.title}
            </Text>
            <ActualTierTag novel={item} />
          </View>
          
          {/* 2ì¤„: ìž‘ê°€ Â· ìž¥ë¥´ + ìš°ì¸¡ ìƒíƒœ ì•„ì´ì½˜ */}
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: 4 }}>
            <Text style={{ color: theme.text, fontSize: 13, flex: 1 }} numberOfLines={1}>
              {item.author || "ìž‘ê°€ ë¯¸ìƒ"}
              {getFirstGenre(item.major_genre) && <Text style={{ color: theme.sub }}> Â· {getFirstGenre(item.major_genre)}</Text>}
              {getFirstGenre(item.sub_genre) && <Text style={{ color: theme.sub }}> Â· {getFirstGenre(item.sub_genre)}</Text>}
            </Text>
            <View style={{ flexDirection: "row", alignItems: "center", marginLeft: 8 }}>
              <StatusIcon status={item.status} />
              <WorkStatusIcon workStatus={item.work_status} />
              <GaidenStatusIcon gaidenStatus={item.gaiden_status} />
            </View>
          </View>
          
          {/* 3ì¤„: ë ˆì´íŒ… ì •ë³´ */}
          <View style={{ flexDirection: "row", alignItems: "center", marginBottom: 4 }}>
            <Text style={{ color: theme.sub, fontSize: 12 }}>
              <Text style={{ fontWeight: "700", color: theme.text }}>{item.rating.toFixed(1)}</Text>
              <Text> Â· W{item.wins}/L{item.losses} Â· ìŠ¹ë¥  </Text>
              <Text style={{ fontWeight: "600" }}>{winRate}%</Text>
              <Text> Â· RD {Math.round(item.rd)}</Text>
            </Text>
          </View>
          
          {/* 4ì¤„: ì½ì€ íšŒì°¨ + í”Œëž«í¼ */}
          <Text style={{ color: theme.sub, fontSize: 12 }} numberOfLines={1}>
            ðŸ“– {episodeText} Â· {plats.length > 0 ? plats.join(", ") : "í”Œëž«í¼ ë¯¸ì§€ì •"}
          </Text>
          
          {/* ìˆ˜ìƒ ë±ƒì§€ */}
          {hasAwards && <AwardsRow awardsJson={item.awards} />}
        </View>
      </View>
      
      {/* í•˜ë‹¨: ë§í¬ ë²„íŠ¼ */}
      {!compareMode && item.link && (
        <TouchableOpacity 
          onPress={onLinkPress}
          style={{ marginTop: 8, alignSelf: "flex-end" }}
        >
          <Text style={{ fontSize: 13, color: theme.primary }}>ðŸ”— ë°”ë¡œê°€ê¸°</Text>
        </TouchableOpacity>
      )}
    </TouchableOpacity>
  );
}, (prevProps, nextProps) => {
  // ì»¤ìŠ¤í…€ ë¹„êµ: í•„ìˆ˜ í•„ë“œë§Œ ë¹„êµí•˜ì—¬ ë¶ˆí•„ìš”í•œ ë¦¬ë Œë”ë§ ë°©ì§€
  return (
    prevProps.item.id === nextProps.item.id &&
    prevProps.item.rating === nextProps.item.rating &&
    prevProps.item.wins === nextProps.item.wins &&
    prevProps.item.losses === nextProps.item.losses &&
    prevProps.item.pinned === nextProps.item.pinned &&
    prevProps.item.cover_image === nextProps.item.cover_image &&
    prevProps.item.title === nextProps.item.title &&
    prevProps.item.status === nextProps.item.status &&
    prevProps.item.work_status === nextProps.item.work_status &&
    prevProps.item.read_count === nextProps.item.read_count &&
    prevProps.index === nextProps.index &&
    prevProps.isComparing === nextProps.isComparing &&
    prevProps.compareMode === nextProps.compareMode &&
    prevProps.isDark === nextProps.isDark
  );
});

